create function app.phase2_staff_id() returns uuid language sql stable security definer set search_path='' as $$ select id from public.staff_members where account_id=app.account_id() and org_id=app.org_id() and active $$;
create function app.phase2_is_team(p_patient uuid,p_kind text default null) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.care_team_assignments where org_id=app.org_id() and patient_id=p_patient and staff_member_id=app.phase2_staff_id() and starts_at<=now() and (ends_at is null or now()<ends_at) and (p_kind is null or assignment_kind=p_kind)) $$;
create function app.phase2_restricted(p_patient uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.restricted_record_flags where org_id=app.org_id() and patient_id=p_patient and active) $$;
create function app.chart_entry(p_patient uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare r text:=app.current_role(); s uuid:=app.phase2_staff_id(); site uuid; team boolean; restricted boolean; opened boolean; begin
if s is null or r is null or r not in ('physician','pmhnp','nurse_rn','lvn','therapist','sud_counselor','clinical_trainee','medical_assistant','ecm_provider','cf_care_manager','peer_specialist','community_health_worker','clinical_coordinator') then return jsonb_build_object('ok',false,'reason','role'); end if;
if not exists(select 1 from public.patients where org_id=app.org_id() and id=p_patient) then return jsonb_build_object('ok',false,'reason','missing'); end if;
select site_id into site from public.patient_site_enrollments where org_id=app.org_id() and patient_id=p_patient and starts_at<=now() and (ends_at is null or now()<ends_at) order by starts_at desc,id limit 1;
if site is null or not exists(select 1 from public.staff_site_assignments where org_id=app.org_id() and staff_member_id=s and site_id=site and starts_at<=now() and (ends_at is null or now()<ends_at)) then return jsonb_build_object('ok',false,'reason','site'); end if;
team:=app.phase2_is_team(p_patient); restricted:=app.phase2_restricted(p_patient);
opened:=exists(select 1 from public.restricted_record_opens o join public.acting_role_sessions rs on rs.id=o.acting_session_id and rs.org_id=o.org_id where o.patient_id=p_patient and o.account_id=app.account_id() and o.org_id=app.org_id() and rs.ended_at is null and rs.role=r);
return jsonb_build_object('ok',not restricted or team or opened,'entryEligible',true,'restricted',restricted,'careTeam',team,'outsideCaseload',not team,'searchable',not restricted or team,'reason',case when restricted and not team and not opened then 'Restricted record — reason required' else null end); end $$;
create function app.phase2_chart_read(p_patient uuid,p_class text) returns boolean language sql stable security definer set search_path='' as $$ select coalesce((app.chart_entry(p_patient)->>'ok')::boolean,false) and exists(select 1 from app.can_access(p_class,p_patient) where level<>'none') $$;
create function app.phase2_intake(p_referral uuid,p_packet boolean default false) returns boolean language plpgsql stable security definer set search_path='' as $$ declare r public.referrals; role_name text:=app.current_role(); begin
if app.phase2_staff_id() is null or role_name not in ('intake_coordinator','sys_admin','clinical_coordinator') then return false; end if;
select * into r from public.referrals where id=p_referral and org_id=app.org_id(); if r.id is null then return false; end if;
if role_name='intake_coordinator' and exists(select 1 from public.intake_checklists where referral_id=r.id and org_id=r.org_id and completed_at is not null) then return false; end if;
if r.linked_patient_id is not null and app.phase2_restricted(r.linked_patient_id) then return false; end if;
return true; end $$;
create function app.phase2_treatment_consent(p_patient uuid) returns boolean language sql stable security definer set search_path='' as $$ select p_patient is not null and not app.phase2_restricted(p_patient) and (app.consent_covers(p_patient,'part2_tpo_single','adelante-program','tpo') or app.consent_covers(p_patient,'part2_tpo_single','adelante-program','treatment') or app.consent_covers(p_patient,'part2_tpo_single','Adelante','treatment')) $$;
create function app.phase2_packet_access(p_referral uuid,p_part2 boolean) returns boolean language plpgsql stable security definer set search_path='' as $$ declare p uuid; begin
select linked_patient_id into p from public.referrals where id=p_referral and org_id=app.org_id();
if app.owns_patient(p) then return true; end if;
if app.phase2_intake(p_referral,true) then return not p_part2 or app.phase2_treatment_consent(p); end if;
return p is not null and exists(select 1 from public.intake_checklists where org_id=app.org_id() and referral_id=p_referral and completed_at is not null) and (app.phase2_is_team(p,'care_manager') or app.phase2_is_team(p,'clinician')) and app.phase2_chart_read(p,'documents') and (not p_part2 or exists(select 1 from app.can_access('sud_treatment',p) where level<>'none')); end $$;
create function app.packet_documents_view(p_referral uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare p uuid; begin
select linked_patient_id into p from public.referrals where id=p_referral and org_id=app.org_id();
if not app.phase2_intake(p_referral,true) and not app.owns_patient(p) and not (p is not null and app.phase2_chart_read(p,'documents') and (app.phase2_is_team(p,'care_manager') or app.phase2_is_team(p,'clinician')) and exists(select 1 from public.intake_checklists where org_id=app.org_id() and referral_id=p_referral and completed_at is not null)) then return '[]'::jsonb; end if;
return coalesce((select jsonb_agg(case when app.phase2_packet_access(d.referral_id,d.part2_tagged) then jsonb_build_object('id',d.id,'locked',false,'document_type',d.document_type,'source',d.source,'file_name',d.file_name,'contentAvailable',false) else jsonb_build_object('id',d.id,'locked',true,'reason','Part 2 — needs consent covering intake/treatment') end order by d.id) from public.packet_documents d where org_id=app.org_id() and referral_id=p_referral),'[]'::jsonb); end $$;
create function app.advocate_slice_allowed(p_link uuid,p_scope text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.advocate_links l join public.advocates a on a.id=l.advocate_id and a.org_id=l.org_id join public.consent_records c on c.id=l.consent_record_id and c.org_id=l.org_id and c.patient_id=l.patient_id where l.id=p_link and l.org_id=app.org_id() and a.account_id=app.account_id() and l.status='active' and p_scope=any(l.scope) and c.consent_type='advocate_release' and c.status='active' and not c.legacy_unverified and not c.needs_review_after_merge and c.expiry_event_occurred_at is null and c.effective_at<=now() and (c.expires_at is null or now()<=c.expires_at) and c.signature_method<>'verbal_assent' and c.purpose_code='care_coordination' and (c.items is null or p_scope=any(c.items)) and exists(select 1 from jsonb_array_elements(c.recipients) x where x->>'directoryRef'=a.id::text)) $$;
create function app.advocate_view_identity(p_link uuid) returns jsonb language sql stable security definer set search_path='' as $$ select case when app.advocate_slice_allowed(p_link,'demographics') then (select jsonb_build_object('id',p.id,'first_name',p.first_name,'last_name',p.last_name) from public.patients p join public.advocate_links l on l.patient_id=p.id and l.org_id=p.org_id where l.id=p_link and l.org_id=app.org_id()) else jsonb_build_object('id',p_link,'locked',true,'reason','Advocate link and consent required') end $$;
create function app.resolve_crisis_owner(p_patient uuid,p_site uuid,p_category text default null,p_at timestamptz default now()) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare owner uuid; begin
if p_patient is not null and not exists(select 1 from public.patients where id=p_patient and org_id=app.org_id()) then raise exception 'record_unavailable'; end if;
if not exists(select 1 from public.sites where id=p_site and org_id=app.org_id()) then raise exception 'site_unavailable'; end if;
select c.staff_member_id into owner from public.care_team_assignments c join public.staff_members s on s.id=c.staff_member_id and s.org_id=c.org_id where c.org_id=app.org_id() and c.patient_id=p_patient and c.assignment_kind=case when p_category='sdoh' then 'care_manager' else 'clinician' end and s.active and c.starts_at<=p_at and (c.ends_at is null or p_at<c.ends_at) and c.role<>'sys_admin' order by c.starts_at,c.id limit 1;
if owner is not null then return jsonb_build_object('staff_id',owner,'source','assigned','fallback_visible',false); end if;
if p_category is distinct from 'sdoh' then select o.clinician_id into owner from public.on_call_shifts o join public.staff_members s on s.id=o.clinician_id and s.org_id=o.org_id where o.org_id=app.org_id() and o.site_id=p_site and o.starts_at<=p_at and p_at<o.ends_at and s.active and exists(select 1 from public.staff_role_assignments r where r.org_id=o.org_id and r.staff_member_id=s.id and r.active and r.role in ('therapist','pmhnp','physician')) order by o.starts_at,o.id limit 1; end if;
if owner is not null then return jsonb_build_object('staff_id',owner,'source','on_call','fallback_visible',false); end if;
return jsonb_build_object('staff_id',null,'source','clinical_coordinator','fallback_visible',true,'notice','No on-call clinician set — sent to the clinical coordinator'); end $$;
create function app.phase2_guard() returns trigger language plpgsql set search_path='' as $$ declare j jsonb:=to_jsonb(new); r uuid; sid uuid; k text; begin
if j ? 'starts_at' and j->>'ends_at' is not null and (j->>'ends_at')::timestamptz<=(j->>'starts_at')::timestamptz then raise exception 'active_dates_invalid'; end if;
if tg_table_name='on_call_shifts' then if new.ends_at-new.starts_at>interval '7 days' or new.draft_label<>'Draft — pending clinical sign-off' or not exists(select 1 from public.staff_members s join public.staff_role_assignments a on a.staff_member_id=s.id and a.org_id=s.org_id where s.id=new.clinician_id and s.org_id=new.org_id and s.active and a.active and a.role in ('therapist','pmhnp','physician')) then raise exception 'licensed_draft_shift_required'; end if; end if;
if tg_table_name in ('referral_codes','signup_sessions') then foreach k in array array['code_hash','otp_hash','identity_hash'] loop if j ? k and j->>k is not null and j->>k !~ '^[a-f0-9]{64}$' then raise exception 'hash_required'; end if; end loop; end if;
if tg_table_name='referrals' and (new.identity_confidence not in ('verified_source','public_unverified') or new.status not in ('submitted','contacted','enrolled','declined') or (new.dob_unknown and new.dob is not null)) then raise exception 'referral_state_invalid'; end if;
if tg_table_name='advocates' and not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and kind='advocate') then raise exception 'advocate_account_required'; end if;
if tg_table_name='advocate_links' and not exists(select 1 from public.consent_records where id=new.consent_record_id and org_id=new.org_id and patient_id=new.patient_id and consent_type='advocate_release') then raise exception 'advocate_consent_link_required'; end if;
if tg_table_name='identity_review_items' then if exists(select 1 from unnest(new.candidate_patient_ids) x where not exists(select 1 from public.patients p where p.id=x and p.org_id=new.org_id)) or exists(select 1 from unnest(new.candidate_referral_ids) x where not exists(select 1 from public.referrals p where p.id=x and p.org_id=new.org_id)) then raise exception 'candidate_org_invalid'; end if; end if;
if tg_table_name='staging_rows' then if jsonb_typeof(new.identity_fields)<>'object' or exists(select 1 from jsonb_object_keys(new.identity_fields) k where k not in ('first_name','last_name','dob','phone','email','referrer_name','referrer_email','release_date')) then raise exception 'referral_identity_fields_only'; end if; end if;
if tg_table_name in ('packet_documents','intake_packet_needs','staging_imports') then if j->>'source' not in ('referral_form','partner_referral','pre_release_packet') or length(trim(j->>'source_ref'))=0 then raise exception 'packet_source_required'; end if; end if;
if tg_table_name in ('packet_documents','intake_packet_needs') then if new.source='referral_form' then if new.source_ref<>'referral:'||new.referral_id::text then raise exception 'source_reference_required'; end if; elsif not exists(select 1 from public.staging_rows sr join public.staging_imports si on si.id=sr.import_id and si.org_id=sr.org_id where sr.referral_id=new.referral_id and sr.org_id=new.org_id and si.source=new.source and si.source_ref=new.source_ref) then raise exception 'source_reference_required'; end if; end if;
if tg_table_name='packet_documents' then if new.classification not in ('general','part2','sud_related','unclassified') or new.part2_tagged<>(new.classification<>'general') or new.document_type not in ('hra','reentry_plan','medication_list','roi') or new.storage_path is not null then raise exception 'packet_classification_or_storage_invalid'; end if; end if;
if tg_table_name='intake_packet_needs' and (new.need_kind not in ('housing','food','transportation','employment','benefits','legal','education','childcare','other') or new.state not in ('confirmed_still_needed','resolved','unknown')) then raise exception 'need_invalid'; end if;
if tg_table_name in ('signup_safety_scans','pre_chart_triage') and j->>'result_tier' not in ('none','amber','red') then raise exception 'safety_tier_invalid'; end if;
return new; end $$;
do $$ declare t text; begin foreach t in array array['care_team_assignments','patient_site_enrollments','staff_site_assignments','restricted_record_flags','restricted_record_opens','advocates','advocate_links','referrals','referral_codes','referral_status_updates','referral_outreach_log','signup_sessions','signup_attempts','signup_safety_scans','identity_review_items','account_support_items','website_inbox_items','intake_checklists','intake_form_status','intake_packet_needs','pre_chart_triage','first_visit_handoffs','staging_imports','staging_rows','packet_documents','on_call_shifts'] loop execute format('create trigger phase2_validate before insert or update on public.%I for each row execute function app.phase2_guard()',t); end loop; end $$;
create policy staff_chart_identity on public.patients for select to authenticated using(org_id=app.org_id() and app.phase2_chart_read(id,'demographics') and (app.chart_entry(id)->>'searchable')::boolean);
create policy staff_chart_contacts on public.patient_contacts for select to authenticated using(org_id=app.org_id() and app.phase2_chart_read(patient_id,'demographics'));
create policy staff_chart_consents on public.consent_records for select to authenticated using(org_id=app.org_id() and app.phase2_chart_read(patient_id,'consent_ledger'));
create policy team_context on public.care_team_assignments for select to authenticated using(org_id=app.org_id() and (app.owns_patient(patient_id) or app.phase2_chart_read(patient_id,'care_coordination')));
create policy patient_enrollment on public.patient_site_enrollments for select to authenticated using(org_id=app.org_id() and (app.owns_patient(patient_id) or app.phase2_chart_read(patient_id,'demographics')));
create policy own_work_sites on public.staff_site_assignments for select to authenticated using(org_id=app.org_id() and staff_member_id=app.phase2_staff_id());
create policy visible_restriction on public.restricted_record_flags for select to authenticated using(org_id=app.org_id() and app.phase2_chart_read(patient_id,'demographics'));
create policy own_restricted_open on public.restricted_record_opens for select to authenticated using(org_id=app.org_id() and (account_id=app.account_id() or app.current_role() in ('sys_admin','clinical_coordinator')));
create policy intake_referral on public.referrals for select to authenticated using(org_id=app.org_id() and (app.phase2_intake(id) or app.owns_patient(linked_patient_id) or (app.phase2_chart_read(linked_patient_id,'demographics') and app.phase2_is_team(linked_patient_id))));
create policy identity_lane on public.identity_review_items for select to authenticated using(org_id=app.org_id() and app.current_role() in ('intake_coordinator','sys_admin','clinical_coordinator') and (patient_id is null or not app.phase2_restricted(patient_id)) and not exists(select 1 from unnest(candidate_patient_ids) p where app.phase2_restricted(p)));
create policy support_lane on public.account_support_items for select to authenticated using(org_id=app.org_id() and exists(select 1 from app.can_access('account_support') where level<>'none'));
create policy website_lane on public.website_inbox_items for select to authenticated using(org_id=app.org_id() and app.current_role()='sys_admin');
create policy own_signup on public.signup_sessions for select to authenticated using(org_id=app.org_id() and account_id=app.account_id());
create policy clinical_triage on public.pre_chart_triage for select to authenticated using(org_id=app.org_id() and (app.current_role() in ('clinical_coordinator','sys_admin') or (owner_staff_id=app.phase2_staff_id() and app.current_role() in ('therapist','physician','pmhnp','ecm_provider'))));
create policy visible_on_call on public.on_call_shifts for select to authenticated using(org_id=app.org_id() and app.phase2_staff_id() is not null);
create policy packet_general_only on public.packet_documents for select to authenticated using(org_id=app.org_id() and not part2_tagged and app.phase2_packet_access(referral_id,false));
create policy packet_needs on public.intake_packet_needs for select to authenticated using(org_id=app.org_id() and (app.phase2_intake(referral_id) or exists(select 1 from public.referrals r where r.id=referral_id and r.org_id=org_id and app.phase2_chart_read(r.linked_patient_id,'sdoh') and app.phase2_is_team(r.linked_patient_id))) and (not part2_tagged or exists(select 1 from public.referrals r where r.id=referral_id and r.org_id=org_id and app.phase2_treatment_consent(r.linked_patient_id))));
do $$ declare t text; begin foreach t in array array['referral_status_updates','referral_outreach_log','intake_checklists','intake_form_status','first_visit_handoffs'] loop execute format('create policy intake_scoped on public.%I for select to authenticated using(org_id=app.org_id() and (app.phase2_intake(referral_id) or exists(select 1 from public.referrals r where r.id=referral_id and r.org_id=app.org_id() and app.owns_patient(r.linked_patient_id))))',t); end loop; end $$;
create policy staging_operator on public.staging_imports for select to authenticated using(org_id=app.org_id() and app.current_role() in ('intake_coordinator','clinical_coordinator','sys_admin'));
create policy staging_referral on public.staging_rows for select to authenticated using(org_id=app.org_id() and app.phase2_intake(referral_id,true));
create function public.phase2_packet_documents(p_referral uuid) returns jsonb language sql stable security definer set search_path='' as $$ select app.packet_documents_view(p_referral) where exists(select 1 from public.tester_attestations where account_id=app.account_id() and statement_version='fictional-only-v1') $$;
create function public.advocate_view_identity(p_link uuid) returns jsonb language sql stable security definer set search_path='' as $$ select app.advocate_view_identity(p_link) where exists(select 1 from public.tester_attestations where account_id=app.account_id() and statement_version='fictional-only-v1') $$;
revoke all on function public.phase2_packet_documents(uuid),public.advocate_view_identity(uuid) from public,anon,service_role; grant execute on function public.phase2_packet_documents(uuid),public.advocate_view_identity(uuid) to authenticated;
revoke all on function app.phase2_guard() from public,anon,authenticated,service_role;
do $$ declare fn record; begin for fn in select proc.oid::regprocedure f from pg_proc proc join pg_namespace n on n.oid=proc.pronamespace where n.nspname='app' and (proc.proname like 'phase2_%' or proc.proname in ('chart_entry','packet_documents_view','advocate_slice_allowed','advocate_view_identity','resolve_crisis_owner')) loop execute format('revoke all on function %s from public,anon,service_role',fn.f); if fn.f::text not like '%phase2_guard%' then execute format('grant execute on function %s to authenticated',fn.f); end if; end loop; end $$;
notify pgrst,'reload schema';